import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])

    count_n = [0] * 5
    count_m = [0] * 5

    for i in range(1, n + 1):
        count_n[i % 5] += 1

    for j in range(1, m + 1):
        count_m[j % 5] += 1

    total = 0
    for r in range(5):
        needed = (5 - r) % 5
        total += count_n[r] * count_m[needed]

    print(total)

if __name__ == "__main__":
    main()
